mapper.select:
SELECT COUNT(*)
FROM sales_order
WHERE deleted = FALSE
  AND status = 'CONFIRMED'
  AND created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COALESCE(SUM(ordered_total_amount), 0)
FROM sales_order
WHERE deleted = FALSE
  AND status = 'CONFIRMED'
  AND created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COALESCE(SUM(settlement_total_amount), 0)
FROM sales_order
WHERE deleted = FALSE
  AND status = 'CONFIRMED'
  AND created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT customer_name_snapshot AS name,
       COALESCE(SUM(settlement_total_amount), 0) AS amount
FROM sales_order
WHERE deleted = FALSE
  AND status = 'CONFIRMED'
  AND created_at >= #{startTime}
  AND created_at < #{endTime}
GROUP BY customer_id, customer_name_snapshot
ORDER BY amount DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM inventory_movement
WHERE deleted = FALSE
  AND movement_type = #{movementType}
  AND occurred_at >= #{startTime}
  AND occurred_at < #{endTime}

SELECT COUNT(*)
FROM purchase_order
WHERE deleted = FALSE
  AND created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COALESCE(SUM(total_amount), 0)
FROM purchase_order
WHERE deleted = FALSE
  AND created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COUNT(*)
FROM purchase_receipt
WHERE deleted = FALSE
  AND created_at >= #{startTime}
  AND created_at < #{endTime}
